import { Skeleton } from "@/components/ui/skeleton";

import {
  CardGridSkeleton,
  CardListSkeleton,
} from "@/components/Common/SkeletonLoading";

export default function OrganizationLayoutSkeleton() {
  return (
    <div className="p-4">
      <div className="flex min-h-11 items-center">
        <Skeleton className="h-4 w-40" />
      </div>
